#!/usr/bin/env bash
# Creates .env (git-ignored) with random local-only credentials on first run. Never overwrites an existing file.
set -euo pipefail
cd "$(dirname "$0")/.."
if [[ -f .env ]]; then
  exit 0
fi
umask 077
rand() { python3 -c 'import secrets; print(secrets.token_urlsafe(24))'; }
pg=$(rand)
vk=$(rand)
cat > .env <<ENV
# Local development only. Generated by scripts/dev_env.sh. Never commit.
POSTGRES_PASSWORD=${pg}
VALKEY_PASSWORD=${vk}
# Host-side URLs used by tests and tools running outside containers:
DATABASE_URL=postgresql+asyncpg://rdesk:${pg}@127.0.0.1:5432/rdesk
REDIS_URL=redis://:${vk}@127.0.0.1:6379/0
ENV
echo "created .env with fresh local credentials"
